<?php /** @var array<string,mixed> $p */ /** @var list<array<string,mixed>> $events */ /** @var bool $canVerify */ use Vertex\Core\View; $url = '/client-payments/' . $p['public_id']; ?>
<div class="page-head"><div><p class="eyebrow">Client payment</p><h1><?= e($p['reference']) ?></h1></div><a class="btn btn-ghost" href="/client-payments">&larr; Payments</a></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><?= View::partial('pbadge', ['kind' => 'payment', 's' => $p['status']]) ?></div><div><span class="muted">Gross</span><br><?= e(money($p['gross_minor'])) ?></div><div><span class="muted">Tax</span><br><?= e(money($p['tax_minor'])) ?></div><div><span class="muted">Refunded</span><br><?= e(money($p['refunded_minor'])) ?></div></div>
    <dl class="detail-list"><dt>Project</dt><dd><a href="/projects/<?= e($p['project_public_id']) ?>"><?= e($p['project_code']) ?> · <?= e($p['project_title']) ?></a></dd><dt>Client</dt><dd><?= e($p['client_name']) ?></dd><dt>Role</dt><dd><?= e(ucfirst($p['payment_role'])) ?></dd>
        <dt>Method</dt><dd><?= e(config("referrals.payment_methods.{$p['method']}", $p['method'])) ?></dd><dt>Transaction reference</dt><dd><?= e($p['external_ref']) ?></dd><?php if ($p['invoice_ref']) : ?><dt>Invoice</dt><dd><?= e($p['invoice_ref']) ?></dd><?php endif; ?>
        <dt>Received on</dt><dd><?= e(local_date($p['received_on'])) ?></dd><dt>Recorded by</dt><dd><?= e($p['recorded_by_name'] ?? '—') ?></dd><?php if ($p['verified_at']) : ?><dt>Verified</dt><dd><?= e($p['verified_by_name'] ?? '') ?> · <?= e(local_time($p['verified_at'])) ?></dd><?php endif; ?>
        <?php if ($p['notes']) : ?><dt>Notes</dt><dd class="prewrap"><?= e($p['notes']) ?></dd><?php endif; ?></dl></div>
<?php if ($canVerify && $p['status'] === 'pending_verification') : ?><div class="panel"><h2>Verify</h2><p class="muted">Confirm against the bank or gateway statement. You cannot verify a payment you recorded.</p>
    <form method="post" action="<?= e($url) ?>/verify" class="form-grid" data-confirm="Verify this payment?"><?= csrf_field() ?><div class="field"><label for="pw">Your password</label><input id="pw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Verify payment</button></div></form></div><?php endif; ?>
<?php if ($canVerify && $p['status'] === 'verified') : ?><div class="panel"><h2>Refund or reverse</h2><p class="muted">Recording a refund never deletes the payment. Commission built on it is recalculated and, if already approved, adjusted with a separate line.</p>
    <form method="post" action="<?= e($url) ?>/refund" class="form-grid" data-confirm="Record this refund?"><?= csrf_field() ?>
        <div class="field"><label for="ty">Type</label><select id="ty" name="type"><option value="refund">Refund</option><option value="chargeback">Chargeback</option><option value="reversed">Entire payment reversed / bounced</option></select></div>
        <div class="field"><label for="am">Amount (₹, not needed for a full reversal)</label><input id="am" name="amount" inputmode="decimal"></div><div class="field"><label for="rr">Reason (required)</label><input id="rr" name="reason" required maxlength="255"></div>
        <div class="field"><label for="pw2">Your password</label><input id="pw2" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-danger btn-sm" type="submit">Record</button></div></form></div><?php endif; ?>
<div class="panel"><h2>History</h2><ol class="timeline"><?php foreach ($events as $ev) : ?><li><strong><?= e(ucfirst(str_replace('_', ' ', $ev['event']))) ?></strong><?= $ev['amount_minor'] ? ' · ' . e(money($ev['amount_minor'])) : '' ?> <span class="muted"><?= e(local_time($ev['created_at'])) ?> · <?= e($ev['actor'] ?? 'system') ?></span><?php if ($ev['reason']) : ?><p class="prewrap"><?= e($ev['reason']) ?></p><?php endif; ?></li><?php endforeach; ?></ol></div>
